def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_remaining = 0.5
    return np.where(remaining < 0, -np.inf, 1.0 / (1.0 + np.abs(remaining - optimal_remaining)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.5
    score = 1.0 - np.abs(remaining - target)
    return np.where(remaining < 0, -np.inf, np.maximum(score, 0.0))
